-- 更新日誌與公告：由管理後台維護，前端開啟網站時讀取（GET /api/notices）
-- 沒看過、且還在公告期間內的項目，開啟網站時會跳出一次

-- 更新日誌：改版日（台北時間）當天起 7 天內跳出
CREATE TABLE changelog (
  version TEXT PRIMARY KEY,   -- 版號，例如 v2.3.0；前端以此記錄看過的最新一筆
  date TEXT NOT NULL,         -- 改版日 YYYY-MM-DD（台北時間）
  sections TEXT NOT NULL,     -- JSON：[{"title":"改善","items":[{"text":"…","experimental":true}]}]
  created_time INTEGER NOT NULL,
  updated_time INTEGER NOT NULL
);

-- 公告：開始日到結束日（台北時間，含當天）之間跳出
CREATE TABLE announcements (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  start_date TEXT NOT NULL,   -- YYYY-MM-DD
  end_date TEXT NOT NULL,     -- YYYY-MM-DD（含當天）
  created_time INTEGER NOT NULL,
  updated_time INTEGER NOT NULL
);
CREATE INDEX announcements_end_date ON announcements (end_date);

-- 原本寫在前端 src/config/changelog.ts 的更新日誌，內容相同
INSERT INTO changelog (version, date, sections, created_time, updated_time) VALUES
  ('v2.3.0', '2026-11-02', '[{"title":"系統搬家","items":[{"text":"預約系統已搬到新主機（Cloudflare）。原本使用的主機服務 Deno Deploy 將在 2027 年 4 月關閉，因此提前搬家。所有預約與使用者資料都已完整搬過來，網址與使用方式都不變，LINE 快速查詢、快速預約也照常使用。"}]},{"title":"改善","items":[{"text":"速度變快：在台灣實測，查詢預約的時間從約 0.9 秒縮短到約 0.3 秒，快了約 3 倍；一段時間沒人使用後第一次開啟，從約 4 秒縮短到約 0.7 秒，快了約 6 倍。"},{"text":"網頁載入更輕快：版面樣式改成網站內建的檔案，打開網站時少下載約 120 KB，也不再需要等手機即時產生樣式，網路較慢時更明顯。"},{"text":"多人同時預約同一個時段時，仍然只會有一人成功，不會重複預約。"}]}]', 1793548800003, 1793548800003),
  ('v2.2.0', '2026-10-30', '[{"title":"新功能","items":[{"text":"LIVE 分頁正式上線：依設計師的設計稿實裝，取代原本實驗性的「Today」，放在會議室分頁最左邊。可左右切換前後工作日；上方黃色摘要顯示資料更新時間、可預約與使用中的會議室數量；每間會議室的卡片會列出還能預約的時段與當天的時間軸，按「立即預約」即可帶入最近的空檔。"}]},{"title":"改善","items":[{"text":"週六不再上班：週檢視與日檢視只顯示週一到週五，左右切換與滑動會跳過週末；週末開啟網站時從下週一開始顯示。"},{"text":"週六、週日不開放預約（網頁與 LINE 快速預約皆同）；已經預約在週末的會議仍可修改名稱、人數或取消。"},{"text":"會議室照片在進入網站時就一起載好，切換會議室或分頁不會再重新下載。"},{"text":"背景更新預約資料時，改在行事曆上緣顯示一條細線，不再遮住行事曆；很快完成的更新不會顯示。"}]},{"title":"修正","items":[{"text":"選擇 08:45 開始或 18:15 結束時，時間欄位不再被誤判為超出可預約時段。"}]}]', 1793289600002, 1793289600002),
  ('v2.1.0', '2026-10-30', '[{"title":"新功能","items":[{"text":"LINE 官方帳號恢復「快速查詢」：傳送「快速查詢」即可查看今天各會議室的預約狀況。"},{"text":"LINE 官方帳號恢復「快速預約」：傳送「快速預約」後，複製回覆的模板填入預約人（行編）與會議室（A / B / S）再送出，即可預約今天的時段。預約成功會回覆一組編輯密碼，可在網頁修改或取消。"},{"text":"新增「Today」分頁（會議室分頁最右邊）：一次查看三間會議室現在是否使用中、還空閒多久，以及今日時間表；按卡片可進入該會議室的週檢視，按「＋」可直接預約最近的空檔。此功能尚未與設計師討論，畫面之後可能調整。","experimental":true}]},{"title":"改善","items":[{"text":"時段衝突時會列出重疊的預約，並建議同時段有空的會議室或當天最近的空檔。"},{"text":"修改預約失敗（密碼錯誤、時段衝突）時，已填的內容會保留，錯誤原因直接顯示在修改視窗。"},{"text":"在預約資訊輸入的編輯密碼，進入修改時會自動帶入，不用再輸入一次。"},{"text":"會記住上次選擇的會議室、檢視模式與預約時輸入的行編。"},{"text":"新增預約的預設時間改為下一個整點或半點，時間以 5 分鐘為單位選擇。"},{"text":"切換會議室、前後切換幾週都不需要重新讀取，畫面立即切換；要取得最新的預約，再點一次目前的會議室分頁即可重新讀取。"},{"text":"手機可在行事曆上左右滑動切換日、週、月，畫面會跟著手指滑動。"},{"text":"同時預約多間會議室時，預約資訊會顯示同組的會議室；刪除前會提醒只取消該間。"},{"text":"月檢視一天超過 4 場時以「+N」表示。"},{"text":"小尺寸手機的日期列不再超出畫面；手機橫放時可整頁捲動；畫面較矮時預約視窗可捲動，「預定」按鈕不會被切掉。"},{"text":"預約資料載入失敗時會跳出提示，避免誤以為沒有人預約。"}]},{"title":"安全性","items":[{"text":"兩人同時預約同一間會議室的同一時段時，系統會排隊逐一檢查，不會再出現重複預約。"},{"text":"修正部分修改過的預約未被列入衝突檢查的問題。"},{"text":"預約資料不再對外提供編輯密碼與部門、組別代碼；預約者沒有姓名時只顯示行編後 4 碼。"},{"text":"修改預約時只接受會議名稱、人數、會議室與時間，預約人等其他資料無法被竄改。"},{"text":"預約服務只接受本網站的請求，系統紀錄中的密碼會自動遮蔽。"},{"text":"LINE 官方帳號的訊息會驗證來源，偽造的請求無法預約。"}]}]', 1793289600001, 1793289600001);
